examples.template:
Column {
    TopAppBar(
        title = {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                Box(
                    modifier = Modifier.size(MonarchTheme.spacing.space8).background(MonarchTheme.colors.bgMuted, MonarchTheme.shapes.md),
                    contentAlignment = Alignment.Center,
                ) { MonarchText(text = "R", style = MonarchTextStyle.BodyStrong) }
                Text(
                    text = {{product}},
                    modifier = Modifier.semantics { heading() },
                    style = MonarchTheme.typography.bodyStrong,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        },
        actions = {
            MonarchNotificationsBell(onClick = { /* Open notifications. */ }, unreadCount = 0) {
                MonarchIcon(SampleIcons.Bell, contentDescription = null)
            }
            Box {
                MonarchIconButton(label = "Account: " + {{account.name}}, onClick = { accountOpen = true }) {
                    MonarchAvatar(image = null, name = {{account.name}}, size = MonarchAvatarSize.Sm, decorative = true)
                }
                MonarchMenu(expanded = accountOpen, onDismissRequest = { accountOpen = false }) {
                    MonarchText(
                        text = {{account.email}},
                        modifier = Modifier.padding(
                            horizontal = MonarchTheme.spacing.space3,
                            vertical = MonarchTheme.spacing.space2,
                        ),
                        color = MonarchTheme.colors.textMuted,
                    )
                    MonarchMenuDivider()
                    MonarchMenuItem(text = "Profile and preferences", onClick = { accountOpen = false })
                    MonarchMenuItem(text = "Rook account", onClick = { accountOpen = false })
                    MonarchMenuItem(text = "Sign out", onClick = { accountOpen = false }, destructive = true)
                }
            }
        },
    )
    MonarchSearchBar(
        query = query,
        onQueryChange = { query = it },
        onSearch = { /* Run the search. */ },
        modifier = Modifier.fillMaxWidth().padding(horizontal = MonarchTheme.spacing.space4),
        placeholder = {{search}},
    )
}

